successful_execution_receipts.command:
cd $(git rev-parse --show-toplevel) && python3 - <<'EOF'
p='vm/runtime/error.go'
s=open(p).read()
old='''// NormalizePanic converts any panic value into a classified runtime error.
func NormalizePanic(v any) *Error {
	if e, ok := v.(*Error); ok {
		return e
	}
	if e, ok := v.(error); ok {
		return &Error{
			Type:    CustomError,
			Message: e.Error(),
			Err:     e,
		}
	}
	return &Error{
		Type:    CustomError,
		Message: fmt.Sprintf("%v", v),
	}
}'''
new='''// NormalizePanic converts any panic value into a classified runtime error.
func NormalizePanic(v any) *Error {
	switch e := v.(type) {
	case *Error:
		return e
	case Error:
		ee := e
		return &ee
	case error:
		return &Error{
			Type:    CustomError,
			Message: e.Error(),
			Err:     e,
		}
	}
	return &Error{
		Type:    CustomError,
		Message: fmt.Sprintf("%v", v),
	}
}'''
assert old in s
s=s.replace(old,new)
open(p,'w').write(s)
print("done")
EOF
go test . 2>&1 | tail -5
